import AppKit
import Foundation
import TridaChatCore

/// What the UI agent has done during one message: the clicks and typing so far (the decision state's
/// "actions so far"), the last element listing the model saw, and whether the user allowed every UI
/// action for this message.
struct UISession {
    var history: [String] = []
    var lastScreen: UIAgent.Screen?
    var allowAll = false
}

/// The UI-agent tools. Which element to click is not generated by the chat model: it is a typed decision
/// (POST /v1/decide) through Zoro-1's pointer head, over the target app's accessibility elements, as in the
/// screen-agent demo. When the decision is unsure (top probability below the threshold) the server
/// reasons once with self-spec generation and decides again with the reasoning in the state.
@MainActor
enum UITools {
    static let names: Set<String> = ["ui_elements", "ui_click", "ui_type", "ui_key", "open_app"]
    /// Every tool here except ui_elements changes something in another app; ask (or "allow all").
    static let needsApproval: Set<String> = ["ui_click", "ui_type", "ui_key", "open_app"]

    /// Same wording as the screen-agent demo.
    static let clickInstruction = "You operate this app for the user. Which element should be clicked next to make "
        + "progress towards the goal? If the goal needs a change saved or confirmed, do that after making the change."
    static let fieldInstruction = "You operate this app for the user. Which field should the text be typed into to "
        + "make progress towards the goal?"

    static let askBelow = 0.4             // still ask, even with "allow all", when the final pick is this unsure

    private static func fn(_ name: String, _ desc: String, _ props: [String: Any], _ required: [String] = []) -> [String: Any] {
        ["type": "function",
         "function": ["name": name, "description": desc,
                      "parameters": ["type": "object", "properties": props, "required": required]]]
    }

    static var specs: [[String: Any]] {
        let str: [String: Any] = ["type": "string"]
        return [
            fn("ui_elements", "List the clickable elements of the app the user is working in (its focused window and "
               + "menu bar), numbered, e.g. \"[3] button 'Send'\".", [:]),
            fn("ui_click", "Click the next element in that app towards a goal. You do not pick the element: a decision "
               + "model looks at the current elements and picks the one that makes progress, so call it once per step "
               + "with the user's whole goal (the same text each time), then check the elements it returns.",
               ["goal": ["type": "string", "description": "The user's goal in this app, in full, e.g. "
                         + "\"Turn on Do Not Disturb and close the settings\"."]], ["goal"]),
            fn("ui_type", "Type text into a text field of that app. field is the element number from the latest "
               + "listing; without it the text goes to the focused field (or a decision picks the field).",
               ["text": str, "field": ["type": "integer"], "goal": str,
                "submit": ["type": "boolean", "description": "Press Return afterwards."]], ["text"]),
            fn("ui_key", "Press a key or shortcut in that app, e.g. \"return\", \"esc\", \"tab\", \"cmd+s\", "
               + "\"cmd+shift+n\".", ["keys": str], ["keys"]),
            fn("open_app", "Open (or bring forward) an app by name, e.g. \"Notes\", and operate it from now on.",
               ["name": str], ["name"]),
        ]
    }

    static func systemPrompt(target: String) -> String {
        "You can operate the app the user is working in (now: \(target)) with ui_elements, ui_click, ui_type, ui_key "
            + "and open_app. For a task in an app: open_app if needed, then call ui_click with the user's whole goal "
            + "until the elements show it is done, using ui_type for text. The user approves each action. Never type "
            + "passwords; ask the user to."
    }

    static func describe(_ call: ToolCall) -> String {
        let a = call.argumentDict
        switch call.name {
        case "ui_key": return "Press \(a["keys"] as? String ?? "?") in \(UIAgent.shared.targetName)."
        case "open_app": return "Open \(a["name"] as? String ?? "?") and let the model operate it."
        default: return "\(call.name)(\(call.arguments))"
        }
    }

    // MARK: - decision requests

    /// The decision state, in the screen-agent demo's key order ("text" variant: the element list is in the state).
    static func state(_ screen: UIAgent.Screen, goal: String, history: [String], elements: [UIElement]) -> OrderedJSON {
        let app = screen.window.isEmpty ? screen.app : "\(screen.app) (window '\(screen.window)')"
        return .object([
            ("app", .string(app)),
            ("goal", .string(goal)),
            ("actions so far", history.isEmpty ? OrderedJSON.string("(none)") : OrderedJSON.strings(history)),
            ("screen", .strings(elements.map(\.describe))),
        ])
    }

    static func ranking(_ d: ChoiceDecision, _ options: [UIElement], top n: Int = 3) -> String {
        var out: [String] = []
        for (key, p) in d.ranked.prefix(n) {
            guard let i = Int(key), i >= 1, i <= options.count else { continue }
            out.append("\(options[i - 1].describe) " + String(format: "%.2f", p))
        }
        return out.joined(separator: "; ")
    }

    static func reasoningNote(_ d: ChoiceDecision) -> String {
        guard d.escalated else { return "" }
        if let cut = d.cut { return "\nReasoning cut off (\(cut)); the direct decision was used." }
        guard let r = d.reasoning?.trimmingCharacters(in: .whitespacesAndNewlines), !r.isEmpty else { return "" }
        return "\nReasoned first (the direct decision was unsure): " + (r.count > 600 ? String(r.prefix(600)) + "…" : r)
    }
}

// MARK: - running the tools

extension AppState {
    /// The UI tools are offered in agent mode when the UI agent is on and the served checkpoint has a decision head.
    var uiToolsActive: Bool { settings.agentMode && uiAgentEnabled && supportsDecision }

    /// Runs one UI tool. `progress` updates the tool card while it runs; approvals go through the usual sheet.
    func runUITool(_ call: ToolCall, progress: @escaping (String) -> Void) async -> ToolOutput {
        let agent = UIAgent.shared
        let a = call.argumentDict
        if call.name != "open_app", !UIAgent.trusted {
            UIAgent.requestTrust()
            return ToolOutput(text: "error: Zoro-1 Chat does not have the Accessibility permission yet. Tell the user to "
                + "allow it in System Settings → Privacy & Security → Accessibility (Settings → Agent has a button), "
                + "then try again.")
        }
        switch call.name {
        case "ui_elements":
            return elementsOutput(prefix: "")

        case "open_app":
            guard let name = a["name"] as? String, !name.isEmpty else { return ToolOutput(text: "error: missing argument 'name'") }
            guard await approveUI(call.name, "Open \(name) and let the model operate it.") else { return denied }
            if let err = await agent.openApp(name) { return ToolOutput(text: "error: " + err) }
            uiSession.history.append("opened \(name)")
            return elementsOutput(prefix: "Opened \(name).\n")

        case "ui_key":
            guard let keys = a["keys"] as? String, !keys.isEmpty else { return ToolOutput(text: "error: missing argument 'keys'") }
            guard await approveUI(call.name, "Press \(keys) in \(agent.targetName).") else { return denied }
            if let err = await agent.key(keys) { return ToolOutput(text: "error: " + err) }
            uiSession.history.append("pressed \(keys)")
            try? await Task.sleep(nanoseconds: 600_000_000)
            return elementsOutput(prefix: "Pressed \(keys).\n")

        case "ui_click":
            guard let goal = (a["goal"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines), !goal.isEmpty else {
                return ToolOutput(text: "error: missing argument 'goal'")
            }
            guard let screen = agent.screen() else { return noTarget }
            uiSession.lastScreen = screen
            guard !screen.elements.isEmpty else {
                return ToolOutput(text: "error: \(screen.app) shows no clickable elements (is its window open?)")
            }
            progress("Deciding among \(screen.elements.count) elements of \(screen.app)…")
            let decision: ChoiceDecision
            do {
                decision = try await decide(screen, goal: goal, question: "click", instruction: UITools.clickInstruction,
                                            options: screen.elements, progress: progress)
            } catch {
                return ToolOutput(text: "error: the decision failed: \(error.localizedDescription)")
            }
            guard let i = Int(decision.choice), i >= 1, i <= screen.elements.count else {
                return ToolOutput(text: "error: the decision returned an unknown option \(decision.choice)")
            }
            let el = screen.elements[i - 1]
            let note = UITools.reasoningNote(decision)
            let detail = "Click [\(el.n)] \(el.describe) in \(screen.app)?\n\nDecision: \(decision.summary)\n"
                + "Top options: \(UITools.ranking(decision, screen.elements))" + note
            progress("Decided: [\(el.n)] \(el.describe) (\(decision.summary))")
            guard await approveUI(call.name, detail, force: decision.top < UITools.askBelow) else {
                return ToolOutput(text: "user denied clicking [\(el.n)] \(el.describe). Ask the user what to do instead.")
            }
            guard await agent.press(el) else { return ToolOutput(text: "error: could not click \(el.describe)") }
            uiSession.history.append(el.describe)
            try? await Task.sleep(nanoseconds: 600_000_000)
            return elementsOutput(prefix: "Clicked [\(el.n)] \(el.describe) (\(decision.summary)).\(note)\n")

        case "ui_type":
            guard let text = a["text"] as? String, !text.isEmpty else { return ToolOutput(text: "error: missing argument 'text'") }
            guard let screen = uiSession.lastScreen ?? agent.screen() else { return noTarget }
            let fields = screen.elements.filter(\.isTextEntry)
            var field: UIElement?
            var how = ""
            if let n = (a["field"] as? Int) ?? (a["field"] as? String).flatMap({ Int($0) }) {
                guard let f = screen.elements.first(where: { $0.n == n }) else {
                    return ToolOutput(text: "error: no element [\(n)] in the latest listing; call ui_elements")
                }
                field = f
            } else if !fields.contains(where: { $0.state.contains("focused") }), fields.count == 1 {
                field = fields[0]
            } else if !fields.contains(where: { $0.state.contains("focused") }), fields.count > 1 {
                let goal = (a["goal"] as? String) ?? "type '\(text)'"
                progress("Deciding which of \(fields.count) fields to type into…")
                do {
                    let d = try await decide(screen, goal: goal, question: "field", instruction: UITools.fieldInstruction,
                                             options: fields, progress: progress)
                    if let i = Int(d.choice), i >= 1, i <= fields.count {
                        field = fields[i - 1]
                        how = " (field chosen by decision, \(d.summary))"
                    }
                } catch {
                    return ToolOutput(text: "error: the decision failed: \(error.localizedDescription)")
                }
            }
            if field?.isSecure == true { return ToolOutput(text: "refused: that is a password field; ask the user to type it") }
            let submit = a["submit"] as? Bool ?? false
            let target = field.map { "[\($0.n)] \($0.describe)" } ?? "the focused field"
            let shown = text.count > 400 ? String(text.prefix(400)) + "…" : text
            guard await approveUI(call.name, "Type into \(target) in \(screen.app)\(how):\n\n\(shown)"
                                  + (submit ? "\n\nthen press Return." : "")) else { return denied }
            if let err = await agent.type(text, into: field) { return ToolOutput(text: err) }
            if submit { _ = await agent.key("return") }
            uiSession.history.append("typed '\(text.count > 60 ? String(text.prefix(60)) + "…" : text)' into "
                                     + (field?.describe ?? "the focused field"))
            try? await Task.sleep(nanoseconds: 400_000_000)
            return elementsOutput(prefix: "Typed into \(target)\(how)\(submit ? " and pressed Return" : "").\n")

        default:
            return ToolOutput(text: "error: unknown tool \(call.name)")
        }
    }

    private var denied: ToolOutput { ToolOutput(text: "user denied") }

    private var noTarget: ToolOutput {
        ToolOutput(text: "error: no app to operate. Ask the user to click into the app first, or call open_app.")
    }

    /// The target app's elements after an action, for the model (and as the next ui_type's field numbers).
    private func elementsOutput(prefix: String) -> ToolOutput {
        guard let screen = UIAgent.shared.screen() else { return ToolOutput(text: prefix + noTarget.text) }
        uiSession.lastScreen = screen
        let title = screen.window.isEmpty ? screen.app : "\(screen.app), window '\(screen.window)'"
        return ToolOutput(text: prefix + "Elements of \(title):\n" + screen.listing)
    }

    private func decide(_ screen: UIAgent.Screen, goal: String, question: String, instruction: String,
                        options: [UIElement], progress: @escaping (String) -> Void) async throws -> ChoiceDecision {
        let image = uiDecisionScreenshot ? await UIAgent.shared.windowScreenshot() : nil
        let state = UITools.state(screen, goal: goal, history: uiSession.history, elements: screen.elements)
        let q = DecisionQuestion.choice(question, instruction,
                                        options.enumerated().map { (String($0.offset + 1), $0.element.describe) })
        let r = try await runDecision(Decision.body(state: state, questions: [q], image: image, settings: decisionSettings),
                                      [q], progress: progress)
        guard let d = ChoiceDecision(result: r, question: question) else {
            throw ChatClientError.http(200, "unexpected decision response")
        }
        return d
    }

    /// Asks before a UI action, unless the user chose "Allow all UI actions for this message"
    /// (`force` asks anyway: an unsure decision).
    private func approveUI(_ tool: String, _ detail: String, force: Bool = false) async -> Bool {
        if uiSession.allowAll && !force { return true }
        NSApp.activate(ignoringOtherApps: true)   // the acted-on app is in front; show the question here
        return await requestApproval(ApprovalRequest(toolName: tool, detail: detail, offerAllowAll: true,
                                                     caption: "Operates \(UIAgent.shared.targetName). Stop with ⌘⎋."))
    }
}
